import React from 'react';
import { Link } from 'react-router-dom';
import type { YearPerson } from '../year_types/YearTypes';

export default function YearPersonCard({ person }: { person: YearPerson }) {
  return (
    <div className="person-card">
      <div className="card-header">
        <div className="person-name">{person.person_name}</div>
      </div>
      <div className="card-image">
        <img src={person.image || '/default-person.png'} alt={person.person_name} />
      </div>
      <div className="card-years">Период: <strong>{person.year_from} — {person.year_to}</strong></div>
      <p>{person.description}</p>
      <div style={{display: 'flex', gap: '8px', marginTop: '8px'}}>
        <Link className="details-btn" to={`/person/${person.id}`}>Подробнее</Link>
        <button className="details-btn" onClick={async () => {
          try {
            const resp = await fetch(`/api/order/add/${person.id}/`, { method: 'POST' });
            if (resp.ok) alert('Добавлено в заявку'); else alert('Ошибка при добавлении');
          } catch (e) {
            alert('Ошибка сети');
          }
        }}>Добавить</button>
      </div>
    </div>
  );
}
